begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
 ('b3000000-0000-0000-0000-000000000001','club-platform@test.example',now(),'{}'),
 ('b3000000-0000-0000-0000-000000000002','club-recipient@test.example',now(),'{}'),
 ('b3000000-0000-0000-0000-000000000003','club-other@test.example',now(),'{}'),
 ('b3000000-0000-0000-0000-000000000004','club-unverified@test.example',null,'{}');
insert into public.platform_roles(user_id,role) values('b3000000-0000-0000-0000-000000000001','system_admin');
insert into public.organizations(id,name,slug) values ('c3000000-0000-0000-0000-000000000001','Admin club A','admin-club-a'),('c3000000-0000-0000-0000-000000000002','Admin club B','admin-club-b');
create temporary table admin_invites(label text,value jsonb);
grant select,insert on admin_invites to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001')$$,'42501','Forbidden','Non-system user cannot list club administrators');
select throws_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001','self')$$,'42501','Forbidden','Non-system user cannot promote themselves');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(public.system_club_admins('c3000000-0000-0000-0000-000000000001')->'administrators'),0,'System administrator can list a club without membership');
select lives_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001','self')$$,'System administrator can bootstrap first club administrator');
select ok(public.has_organization_role('c3000000-0000-0000-0000-000000000001',array['admin']),'Self assignment grants club admin');
select lives_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001','remove','{"userId":"b3000000-0000-0000-0000-000000000001"}')$$,'System administrator can remove the final administrator');
select ok(public.is_organization_member('c3000000-0000-0000-0000-000000000001'),'Removing administration preserves club membership');
select ok(not public.has_organization_role('c3000000-0000-0000-0000-000000000001',array['admin']),'Removed role is no longer admin');
select lives_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001','self')$$,'System administrator can restore a club without administrators');
insert into admin_invites values('first',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-recipient@test.example','tokenHash',repeat('a',64))));
select is(jsonb_array_length(public.system_club_admins('c3000000-0000-0000-0000-000000000002')->'invitations'),1,'Pending invitation is listed');
select ok(not public.has_organization_role('c3000000-0000-0000-0000-000000000002',array['admin']),'Inviting grants no membership to the system administrator');
select throws_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000001','cancel',jsonb_build_object('invitationId',(select value->>'invitationId' from admin_invites where label='first')))$$,'P0002','Invitation not found','Cannot cancel another club invitation');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select is(public.club_admin_invite_context(repeat('a',64)),null::jsonb,'Wrong account cannot preview invitation');
select throws_ok($$select public.accept_club_admin_invite(repeat('a',64))$$,'22023','Invalid invitation','Wrong email cannot accept invitation');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is(public.club_admin_invite_context(repeat('a',64))->>'clubName','Admin club B','Recipient sees the club before accepting');
select is(public.accept_club_admin_invite(repeat('a',64))->>'slug','admin-club-b','Verified recipient can accept');
select ok(public.has_organization_role('c3000000-0000-0000-0000-000000000002',array['admin']),'Recipient becomes club administrator');
select ok(not public.has_platform_role(array['system_admin']),'Acceptance never grants system role');
select throws_ok($$select public.accept_club_admin_invite(repeat('a',64))$$,'22023','Invalid invitation','Invitation cannot be replayed');
select throws_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000002','self')$$,'42501','Forbidden','Club admin does not gain system-role management');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-recipient@test.example','tokenHash',repeat('b',64)))$$,'55000','Already administrator','Existing administrators do not receive redundant invitations');
insert into admin_invites values('unverified',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-unverified@test.example','tokenHash',repeat('b',64))));
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.accept_club_admin_invite(repeat('b',64))$$,'42501','Verified email required','Unverified email cannot accept');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000002','cancel',jsonb_build_object('invitationId',(select value->>'invitationId' from admin_invites where label='unverified')))$$,'System administrator can cancel invitation');
insert into admin_invites values('resend-old',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-other@test.example','tokenHash',repeat('c',64))));
insert into admin_invites values('resend-new',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-other@test.example','tokenHash',repeat('d',64))));
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.accept_club_admin_invite(repeat('c',64))$$,'22023','Invalid invitation','Resending invalidates the previous token');
reset role;
update administration.club_admin_invites set expires_at=now()-interval '1 hour' where token_hash=repeat('d',64);
set local role authenticated;
select throws_ok($$select public.accept_club_admin_invite(repeat('d',64))$$,'22023','Invalid invitation','Expired token cannot be accepted');

select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into admin_invites values('failed',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-other@test.example','tokenHash',repeat('e',64))));
select lives_ok($$select public.system_club_admins('c3000000-0000-0000-0000-000000000002','delivery',jsonb_build_object('invitationId',(select value->>'invitationId' from admin_invites where label='failed'),'sent',false))$$,'Failed email disables its invitation');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.accept_club_admin_invite(repeat('e',64))$$,'22023','Invalid invitation','Failed email token cannot grant administration');
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into admin_invites values('revoked-inviter',public.system_club_admins('c3000000-0000-0000-0000-000000000002','invite',jsonb_build_object('email','club-other@test.example','tokenHash',repeat('f',64))));
reset role;
delete from public.platform_roles where user_id='b3000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b3000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.accept_club_admin_invite(repeat('f',64))$$,'22023','Invalid invitation','Revoked system administrator cannot leave active invitation authority');
select ok(not has_table_privilege('authenticated','administration.club_admin_invites','select'),'Invitation hashes are not exposed to clients');
select ok(not has_function_privilege('anon','public.accept_club_admin_invite(text)','execute'),'Anonymous acceptance has no execute privilege');
select ok(not (select prosecdef from pg_proc where oid='public.system_club_admins(uuid,text,jsonb)'::regprocedure),'System wrapper is security invoker');
select * from finish();
rollback;
